      x: left,
      y: top,
      width: patchWidth,
      height: patchHeight,
      coverage: new Uint8ClampedArray(patchWidth * patchHeight).fill(255),
    }).store;
  }
  return createSelectionMask({
    width: canvas.width,
    height: canvas.height,
    coverageStore: store,
  });
}

