export function selectAll(): DocumentTransform {
  return command('Select all', (document) => ({ ...document, selection: null }));
}

export function setCloneSource(source: CloneSource | null, label?: string): DocumentTransform {
  const owned = source === null ? null : createCloneSource(source.documentX, source.documentY);
  const commandLabel = label ?? (owned === null ? 'Clear clone source' : 'Set clone source');
  assertName(commandLabel, 'Clone source command label');
  return command(commandLabel, (document) => ({
    ...document,
    cloneSource: copyCloneSource(owned),
  }));
}

export function copyCloneSource(source: CloneSource | null | undefined): CloneSource | null {
  if (source == null) return null;
  return createCloneSource(source.documentX, source.documentY);
}

