} from './index.js';

const identity = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 } as const;

afterEach(() => vi.restoreAllMocks());

const redBrush: BrushOptions = {
  mode: 'source-over',
  size: 1,
  hardness: 1,
  opacity: 1,
