    const sourceAlpha = 0.5;
    const destAlpha = 0.5;
    const outputAlpha = sourceAlpha + destAlpha * (1 - sourceAlpha);

    const outputAlphaInt = Math.round(outputAlpha * 255);
    expect(outputAlphaInt).toBe(191);
    expect(outputAlphaInt).toBeGreaterThan(0);
    expect(outputAlphaInt).toBeLessThanOrEqual(255);
  });

  it('tests stroke region allocation efficiency', () => {
    // Verify stroke regions are allocated efficiently
    const strokeWidth = 50;
    const strokeHeight = 50;
    const regionSize = strokeWidth * strokeHeight;

    // Region should be much smaller than full layer
    const layerWidth = 4096;
    const layerHeight = 4096;
    const layerSize = layerWidth * layerHeight;

    expect(regionSize).toBe(2500);
    expect(layerSize).toBe(16777216);
    expect(regionSize).toBeLessThan(layerSize / 100);
  });

  it('validates multi-dab stroke union bounds', () => {
    // Test that multiple dabs are combined correctly
    const dab1 = { x: 100, y: 100 };
    const dab2 = { x: 150, y: 150 };
    const dab3 = { x: 200, y: 200 };
    const radius = 25;

    const dab1Left = Math.max(0, Math.floor(dab1.x - radius));
    const dab1Right = Math.min(1000, Math.ceil(dab1.x + radius));
    const dab2Left = Math.max(0, Math.floor(dab2.x - radius));
    const dab2Right = Math.min(1000, Math.ceil(dab2.x + radius));
    const dab3Left = Math.max(0, Math.floor(dab3.x - radius));
    const dab3Right = Math.min(1000, Math.ceil(dab3.x + radius));

    const unionLeft = Math.min(dab1Left, Math.min(dab2Left, dab3Left));
    const unionRight = Math.max(dab1Right, Math.max(dab2Right, dab3Right));

    expect(unionLeft).toBe(75);
    expect(unionRight).toBe(225);
    expect(unionRight - unionLeft).toBe(150);
  });

  it('tests that stroke bounds are clipped to layer boundaries', () => {
    // Verify stroke bounds are clipped correctly
    const documentX = 10;
    const documentY = 10;
    const radius = 25;
    const layerWidth = 100;
    const layerHeight = 100;

    const left = Math.max(0, Math.floor(documentX - radius));
    const top = Math.max(0, Math.floor(documentY - radius));
    const right = Math.min(layerWidth - 1, Math.ceil(documentX + radius));
    const bottom = Math.min(layerHeight - 1, Math.ceil(documentY + radius));

    expect(left).toBe(0);
    expect(top).toBe(0);
    expect(right).toBe(35);
    expect(bottom).toBe(35);
    expect(left).toBeGreaterThanOrEqual(0);
    expect(top).toBeGreaterThanOrEqual(0);
    expect(right).toBeLessThan(layerWidth);
    expect(bottom).toBeLessThan(layerHeight);
  });

  it('validates source sampling at document boundaries', () => {
    // Test sampling at document edges
    const sourceWidth = 200;
    const sourceHeight = 200;

    // Sample at origin
    const sampleX1 = Math.max(0, Math.min(sourceWidth - 1, 0));
    const sampleY1 = Math.max(0, Math.min(sourceHeight - 1, 0));
    expect(sampleX1).toBe(0);
    expect(sampleY1).toBe(0);

    // Sample at edge
    const sampleX2 = Math.max(0, Math.min(sourceWidth - 1, sourceWidth - 1));
    const sampleY2 = Math.max(0, Math.min(sourceHeight - 1, sourceHeight - 1));
    expect(sampleX2).toBe(199);
    expect(sampleY2).toBe(199);

    // Sample outside (should clamp)
    const sampleX3 = Math.max(0, Math.min(sourceWidth - 1, sourceWidth + 50));
    const sampleY3 = Math.max(0, Math.min(sourceHeight - 1, sourceHeight + 50));
    expect(sampleX3).toBe(199);
    expect(sampleY3).toBe(199);
  });

  it('tests seamless clone stamp across tile boundaries', () => {
    // Verify clone stamp works across tile boundaries
    const tileSize = 256;
    const pixelX = 255; // Last pixel in first tile
    const pixelY = 255;

    const tileX = Math.floor(pixelX / tileSize);
    const tileY = Math.floor(pixelY / tileSize);
    const localX = pixelX - tileX * tileSize;
    const localY = pixelY - tileY * tileSize;

    expect(tileX).toBe(0);
    expect(tileY).toBe(0);
    expect(localX).toBe(255);
    expect(localY).toBe(255);

    // Next pixel is in second tile
    const nextPixelX = 256;
    const nextTileX = Math.floor(nextPixelX / tileSize);
    const nextLocalX = nextPixelX - nextTileX * tileSize;

    expect(nextTileX).toBe(1);
    expect(nextLocalX).toBe(0);
  });

  it('validates the relationship between source and destination transforms', () => {
    // Test that source and destination transforms are independent
    const sourceTransform = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 };
    const destTransform = { a: 1, b: 0, c: 0, d: 1, e: 100, f: 100 };

    // Each transform should be independently invertible
    const sourceDet = sourceTransform.a * sourceTransform.d - sourceTransform.b * sourceTransform.c;
    const destDet = destTransform.a * destTransform.d - destTransform.b * destTransform.c;

    expect(sourceDet).toBe(1);
    expect(destDet).toBe(1);
    expect(sourceDet).toBeGreaterThan(0);
    expect(destDet).toBeGreaterThan(0);
  });

