    const sourceForPoint1X = sourceOriginX;
    const sourceForPoint1Y = sourceOriginY;
    const sourceForPoint2X = sourceOriginX;
    const sourceForPoint2Y = sourceOriginY;

    expect(sourceForPoint1X).toBe(sourceForPoint2X);
    expect(sourceForPoint1Y).toBe(sourceForPoint2Y);
    expect(sourceForPoint1X).toBe(sourceOriginX);
    expect(sourceForPoint1Y).toBe(sourceOriginY);
  });

  it('tests aligned mode offset preservation', () => {
    // Verify aligned mode preserves offset across points
    const sourceOriginX = 100;
    const sourceOriginY = 100;
    const firstDestX = 200;
    const firstDestY = 200;
    const secondDestX = 250;
    const secondDestY = 250;

    const offsetX = firstDestX - sourceOriginX;
    const offsetY = firstDestY - sourceOriginY;

    const sourceForSecondX = secondDestX - offsetX;
    const sourceForSecondY = secondDestY - offsetY;

    expect(sourceForSecondX).toBe(sourceOriginX);
    expect(sourceForSecondY).toBe(sourceOriginY);
    expect(offsetX).toBe(100);
    expect(offsetY).toBe(100);
  });
});

